// Recovered from the July 20 Deckplate/AI Lantern session (regenerated by transcript replay).
// Assist + ASTRO verification against the delivered inner document.
const fs = require('fs'); const path = require('path');
const { JSDOM } = require("jsdom");
const dom = new JSDOM(fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"),'utf8'),
  { runScripts:'dangerously', url:'http://localhost/', pretendToBeVisual:true });
const w = dom.window, d = w.document;
w.HTMLMediaElement.prototype.play = function(){ return Promise.resolve(); };
w.HTMLMediaElement.prototype.pause = function(){};
let fails = 0;
const check = (n,c) => { console.log((c?'PASS':'FAIL')+'  '+n); if(!c) fails++; };
const near = (a,b,tol) => Math.abs(a-b) <= tol*Math.abs(b);
(async () => {
  d.dispatchEvent(new w.Event('DOMContentLoaded',{bubbles:true}));
  await new Promise(r=>setTimeout(r,30));
  const L = w.Lantern, ev = (e,ctx) => L.formula.evaluate(e, ctx || {deg:false});

  // --- ASTRO numeric ground truth ---
  check('ORBITT ISS ~92.8 min (pre-existing fn, sanity)', near(ev('ORBITT(CONVERT(420+6371,"km","m"))/60'), 92.8, 0.01));
  check('SMAXIS(86164s) -> geostationary 42164 km', near(ev('CONVERT(SMAXIS(86164),"m","km")'), 42164, 0.001));
  check('VISVIVA circular == ORBITV', near(ev('VISVIVA(7000000,7000000)'), ev('ORBITV(7000000)'), 1e-9));
  check('HOHMANN LEO(6678km)->GEO ~3.89 km/s', near(ev('HOHMANN(6678000,42164000)'), 3892, 0.005));
  check('HOHMANNT LEO->GEO ~5.25 h', near(ev('HOHMANNT(6678000,42164000)/3600'), 5.25, 0.02));
  const M=1.1, e=0.5, E=ev('KEPLERE(1.1,0.5)');
  check('KEPLERE solves Kepler equation to 1e-9', Math.abs(E - e*Math.sin(E) - M) < 1e-9);
  check('TRUEANOM at E=0 is 0', Math.abs(ev('TRUEANOM(0,0.3)')) < 1e-12);
  check('ORBR perihelion = a(1-e)', near(ev('ORBR(10000,0.2,0)'), 8000, 1e-9));
  check('SCHWARZ(sun) ~2953 m', near(ev('SCHWARZ(1.989e30)'), 2953, 0.001));
  check('PERIPREC Mercury ~5.02e-7 rad/orbit', near(ev('PERIPREC(5.79e10,0.2056,1.32712e20)'), 5.02e-7, 0.01));
  check('VELDIL ISS speed ~ tiny factor below 1', ev('VELDIL(7660)') < 1 && ev('VELDIL(7660)') > 0.9999);
  check('GRAVDIL inside horizon throws', (()=>{try{ev('GRAVDIL(1000,2000)');return false}catch(err){return true}})());

  // --- ASSIST_CORE headless ---
  const A = L.assist;
  const hits = A.match('how long does the iss take to orbit at 420 km');
  check('card match ranks orbit-period first', hits.length && hits[0].id === 'orbit-period');
  const expr = A.fill(hits[0], { alt_km: 420 });
  check('slot fill composes expression', expr === '=ORBITT(CONVERT(420+6371,"km","m"))/60');
  const run = A.run(expr);
  check('run evaluates ~92.8 min', run.steps.length === 1 && run.steps[0].ok && near(run.value, 92.8, 0.01));
  const run2 = A.run('=SCHWARZ(1.989e30)\n=ANS/1000');
  check('ANS chains between = lines', near(run2.value, 2.953, 0.001));
  check('fill rejects missing slot', (()=>{try{A.fill(hits[0],{});return false}catch(err){return true}})());
  const prompt = A.buildPrompt('molar mass of water', A.match('molar mass of water'));
  check('prompt carries contract + catalog + recipe', /ANSWER:/.test(prompt) && /MOLARMASS/.test(prompt) && /RECIPES/.test(prompt));
  const rep = A.parseReply('thinking...\n=MOLARMASS("H2O")\nANSWER: about 18 g/mol');
  check('parseReply extracts = lines and ANSWER', rep.exprText === '=MOLARMASS("H2O")' && /18/.test(rep.answer));
  check('courier round trip computes 18.015', near(A.run(rep.exprText).value, 18.015, 0.001));
  check('parseReply catches NEED', A.parseReply('NEED: the altitude in km').need !== null);

  // --- ASSIST_APP UI ---
  w.location.hash = 'assist';
  w.dispatchEvent(new w.Event('hashchange'));
  await new Promise(r=>setTimeout(r,40));
  const tiles = [...d.querySelectorAll('.tile .name')].map(n=>n.textContent);
  check('Assist tile registered on home list', tiles.includes('Assist'));
  const q = d.querySelector('input[aria-label="Your question"]');
  check('assist app mounted', !!q);
  q.value = 'how long does a satellite take to orbit at 420 km altitude';
  q.dispatchEvent(new w.Event('input',{bubbles:true}));
  await new Promise(r=>setTimeout(r,20));
  check('recipe list rendered', d.querySelectorAll('.item .t').length >= 1);
  d.querySelector('.item button.primary').click();
  const alt = d.querySelector('input[aria-label="Altitude above the surface"]');
  check('slot form rendered', !!alt);
  alt.value = '420';
  ;[...d.querySelectorAll('button')].find(b=>b.textContent==='Compute').click();
  await new Promise(r=>setTimeout(r,20));
  check('UI computes and shows ~92.8', /92\.8/.test(d.body.textContent));

  // --- server mode against a stubbed OpenAI-compatible endpoint ---
  w.fetch = async (url, opts) => ({
    ok: true, json: async () => ({ choices: [{ message: { content:
      '=ORBITT(CONVERT(420+6371,"km","m"))/60\nANSWER: about 93 minutes' } }] })
  });
  const msel = d.querySelector('select[aria-label="Mode"]');
  msel.value = 'server'; msel.dispatchEvent(new w.Event('change',{bubbles:true}));
  await new Promise(r=>setTimeout(r,20));
  ;[...d.querySelectorAll('button')].find(b=>b.textContent==='Ask').click();
  await new Promise(r=>setTimeout(r,40));
  check('server loop: model text shown + engine verifies 92.8', /about 93 minutes/.test(d.body.textContent) && /92\.8/.test(d.body.textContent));
  check('guide registered for assist', L.guide.has('assist'));

  console.log(fails ? 'ASSIST FAILURES: '+fails : 'ALL ASSIST + ASTRO TESTS PASS');
  process.exit(fails?1:0);
})().catch(e=>{console.error('CRASH',e);process.exit(1);});
